ALL = ['view', 'create', 'edit', 'archive', 'approve', 'export', 'assign', 'cancel', 'refund', 'override',
       'reveal_sensitive', 'import', 'configure']


def grant_owner(apps, schema_editor):
    """Roles are seeded once, so an existing owner role does not pick up the new module from code. Only the owner
    role gets it, and only when an administrator has not already set it by hand."""
    Role = apps.get_model('crm', 'Role')
    for role in Role.objects.filter(code='owner'):
        current = dict(role.grants or {})
        if 'business_desk' not in current:
            current['business_desk'] = {a: 'company' for a in ALL}
            role.grants = current
            role.save(update_fields=['grants'])


def revoke_owner(apps, schema_editor):
    Role = apps.get_model('crm', 'Role')
    for role in Role.objects.filter(code='owner'):
        current = dict(role.grants or {})
        if current.pop('business_desk', None) is not None:
            role.grants = current
            role.save(update_fields=['grants'])


